     1→import { headers } from "next/headers";
     2→import { auth } from "../auth";
     3→import type { AuthPermission } from "./auth-permissions";
     4→import { getUserContext, hasB2BPermissionAsync } from "./unified-permissions";
     5→import type { B2BPermission } from "./b2b-permissions";
     6→
     7→/**
     8→ * Legacy permission checker - uses Better Auth organization permissions
     9→ * This is maintained for backward compatibility with existing B2B organization features
    10→ */
    11→export const hasPermission = async (permission: AuthPermission) => {
    12→  const result = await auth.api.hasPermission({
    13→    headers: await headers(),
    14→    body: {
    15→      permission,
    16→    },
    17→  });
    18→
    19→  return result.success;
    20→};
    21→
    22→/**
    23→ * New unified permission checker
    24→ * Automatically routes to B2C or B2B permissions based on account type
    25→ */
    26→export const hasUnifiedPermission = async (
    27→  permission: AuthPermission | B2BPermission,
    28→) => {
    29→  const userContext = await getUserContext();
    30→
    31→  if (!userContext) {
    32→    return false;
    33→  }
    34→
    35→  // For professionals, use B2B permissions if it's a B2B-specific permission
    36→  if (userContext.accountType === "professional") {
    37→    try {
    38→      // Try B2B permissions first
    39→      return await hasB2BPermissionAsync(permission as B2BPermission);
    40→    } catch {
    41→      // Fall back to legacy organization permissions
    42→      return hasPermission(permission as AuthPermission);
    43→    }
    44→  }
    45→
    46→  // For individuals, B2B permissions don't apply
    47→  return false;
    48→};
