     1→import { headers } from "next/headers";
     2→import { auth } from "../auth";
     3→import { prisma } from "../prisma";
     4→import type { B2CPermission, B2CRole } from "./b2c-permissions";
     5→import { getB2CUserRole, hasB2CPermission } from "./b2c-permissions";
     6→import type { B2BPermission, B2BRole } from "./b2b-permissions";
     7→import { getB2BUserRole, hasB2BPermission } from "./b2b-permissions";
     8→
     9→/**
    10→ * Unified permission system that handles both B2C and B2B permissions
    11→ * based on user account type and organization role
    12→ */
    13→
    14→export type UserContext = {
    15→  id: string;
    16→  email: string;
    17→  accountType: "individual" | "professional";
    18→  organizationRole?: string;
    19→  organizationId?: string;
    20→};
    21→
    22→export type UnifiedPermission = B2CPermission | B2BPermission;
    23→
    24→/**
    25→ * Get current user context with account type and organization info
    26→ */
    27→export async function getUserContext(): Promise<UserContext | null> {
    28→  try {
    29→    const session = await auth.api.getSession({
    30→      headers: await headers(),
    31→    });
    32→
    33→    if (!session?.user) {
    34→      return null;
    35→    }
    36→
    37→    // Get user with account type
    38→    const user = await prisma.user.findUnique({
    39→      where: { id: session.user.id },
    40→      select: {
    41→        id: true,
    42→        email: true,
    43→        accountType: true,
    44→      },
    45→    });
    46→
    47→    if (!user) {
    48→      return null;
    49→    }
    50→
    51→    // Get organization info for professionals
    52→    let organizationRole: string | undefined;
    53→    let organizationId: string | undefined;
    54→
    55→    if (user.accountType === "professional") {
    56→      const member = await prisma.member.findFirst({
    57→        where: { userId: user.id },
    58→        select: {
    59→          role: true,
    60→          organizationId: true,
    61→        },
    62→        orderBy: { createdAt: "desc" }, // Get most recent membership
    63→      });
    64→
    65→      if (member) {
    66→        organizationRole = member.role;
    67→        organizationId = member.organizationId;
    68→      }
    69→    }
    70→
    71→    return {
    72→      id: user.id,
    73→      email: user.email,
    74→      accountType: user.accountType as "individual" | "professional",
    75→      organizationRole,
    76→      organizationId,
    77→    };
    78→  } catch {
    79→    return null;
    80→  }
    81→}
    82→
    83→/**
    84→ * Check if user has permission for a specific resource and action
    85→ */
    86→export async function hasUnifiedPermission(
    87→  resource: string,
    88→  action: string,
    89→): Promise<boolean> {
    90→  try {
    91→    const userContext = await getUserContext();
    92→    if (!userContext) {
    93→      return false;
    94→    }
    95→
    96→    if (userContext.accountType === "individual") {
    97→      // B2C permissions
    98→      const role = getB2CUserRole(userContext.accountType);
    99→      return hasB2CPermission(
   100→        role ?? undefined,
   101→        resource as keyof B2CPermission,
   102→        action,
   103→      );
   104→    } else {
   105→      // B2B permissions
   106→      const role = getB2BUserRole(
   107→        userContext.accountType,
   108→        userContext.organizationRole,
   109→      );
   110→      return hasB2BPermission(
   111→        role ?? undefined,
   112→        resource as keyof B2BPermission,
   113→        action,
   114→      );
   115→    }
   116→  } catch {
   117→    return false;
   118→  }
   119→}
   120→
   121→/**
   122→ * Check B2C specific permissions
   123→ */
   124→export async function hasB2CPermissionAsync(
   125→  permission: B2CPermission,
   126→): Promise<boolean> {
   127→  try {
   128→    const userContext = await getUserContext();
   129→    if (!userContext || userContext.accountType !== "individual") {
   130→      return false;
   131→    }
   132→
   133→    const role = getB2CUserRole(userContext.accountType);
   134→    if (!role) {
   135→      return false;
   136→    }
   137→
   138→    // Check all permissions in the permission object
   139→    for (const [resource, actions] of Object.entries(permission)) {
   140→      if (actions.length === 0) continue;
   141→
   142→      for (const action of actions) {
   143→        if (!hasB2CPermission(role, resource as keyof B2CPermission, action)) {
   144→          return false;
   145→        }
   146→      }
   147→    }
   148→
   149→    return true;
   150→  } catch {
   151→    return false;
   152→  }
   153→}
   154→
   155→/**
   156→ * Check B2B specific permissions
   157→ */
   158→export async function hasB2BPermissionAsync(
   159→  permission: B2BPermission,
   160→): Promise<boolean> {
   161→  try {
   162→    const userContext = await getUserContext();
   163→    if (!userContext || userContext.accountType !== "professional") {
   164→      return false;
   165→    }
   166→
   167→    const role = getB2BUserRole(
   168→      userContext.accountType,
   169→      userContext.organizationRole,
   170→    );
   171→    if (!role) {
   172→      return false;
   173→    }
   174→
   175→    // Check all permissions in the permission object
   176→    for (const [resource, actions] of Object.entries(permission)) {
   177→      if (actions.length === 0) continue;
   178→
   179→      for (const action of actions) {
   180→        if (!hasB2BPermission(role, resource as keyof B2BPermission, action)) {
   181→          return false;
   182→        }
   183→      }
   184→    }
   185→
   186→    return true;
   187→  } catch {
   188→    return false;
   189→  }
   190→}
   191→
   192→/**
   193→ * Get user role based on account type
   194→ */
   195→export async function getUserRole(): Promise<B2CRole | B2BRole | null> {
   196→  try {
   197→    const userContext = await getUserContext();
   198→    if (!userContext) {
   199→      return null;
   200→    }
   201→
   202→    if (userContext.accountType === "individual") {
   203→      return getB2CUserRole(userContext.accountType);
   204→    } else {
   205→      return getB2BUserRole(
   206→        userContext.accountType,
   207→        userContext.organizationRole,
   208→      );
   209→    }
   210→  } catch {
   211→    return null;
   212→  }
   213→}
   214→
   215→/**
   216→ * Guard functions for route protection
   217→ */
   218→
   219→export async function requireB2CPermission(
   220→  permission: B2CPermission,
   221→): Promise<void> {
   222→  const hasPermission = await hasB2CPermissionAsync(permission);
   223→  if (!hasPermission) {
   224→    throw new Error("Insufficient permissions for B2C operation");
   225→  }
   226→}
   227→
   228→export async function requireB2BPermission(
   229→  permission: B2BPermission,
   230→): Promise<void> {
   231→  const hasPermission = await hasB2BPermissionAsync(permission);
   232→  if (!hasPermission) {
   233→    throw new Error("Insufficient permissions for B2B operation");
   234→  }
   235→}
   236→
   237→export async function requireAccountType(
   238→  accountType: "individual" | "professional",
   239→): Promise<void> {
   240→  const userContext = await getUserContext();
   241→  if (!userContext || userContext.accountType !== accountType) {
   242→    throw new Error(`Access denied: ${accountType} account required`);
   243→  }
   244→}
