    11→type PermissionGuardProps = {
    12→  children: ReactNode;
    13→  fallback?: ReactNode;
    14→  redirectTo?: string;
    15→} & (
    16→  | {
    17→      b2cPermission: B2CPermission;
    18→      b2bPermission?: never;
    19→    }
    20→  | {
    21→      b2cPermission?: never;
    22→      b2bPermission: B2BPermission;
    23→    }
    24→  | {
    25→      b2cPermission: B2CPermission;
    26→      b2bPermission: B2BPermission;
    27→    }
    28→);
    29→
    30→/**
    31→ * Permission Guard Component
    32→ * Protects content based on B2C or B2B permissions
    33→ */
    34→export async function PermissionGuard({
    35→  children,
    36→  fallback = null,
    37→  redirectTo,
    38→  b2cPermission,
    39→  b2bPermission,
    40→}: PermissionGuardProps) {
    41→  const userContext = await getUserContext();
    42→
    43→  if (!userContext) {
    44→    if (redirectTo) {
    45→      redirect("/auth/signin");
    46→    }
    47→    return <>{fallback}</>;
    48→  }
    49→
    50→  let hasPermission = false;
    51→
    52→  // Check B2C permissions for individuals
    53→  if (userContext.accountType === "individual" && b2cPermission) {
    54→    hasPermission = await hasB2CPermissionAsync(b2cPermission);
    55→  }
    56→
    57→  // Check B2B permissions for professionals
    58→  if (userContext.accountType === "professional" && b2bPermission) {
    59→    hasPermission = await hasB2BPermissionAsync(b2bPermission);
    60→  }
    61→
    62→  if (!hasPermission) {
    63→    if (redirectTo) {
    64→      redirect(redirectTo);
    65→    }
    66→    return <>{fallback}</>;
    67→  }
    68→
    69→  return <>{children}</>;
    70→}
