    92→    if (redirectTo) {
    93→      redirect("/auth/signin");
    94→    }
    95→    return <>{fallback}</>;
    96→  }
    97→
    98→  if (userContext.accountType !== accountType) {
    99→    if (redirectTo) {
   100→      const defaultRedirect =
   101→        accountType === "individual" ? "/dashboard" : "/orgs";
   102→      redirect(redirectTo || defaultRedirect);
   103→    }
   104→    return <>{fallback}</>;
   105→  }
   106→
   107→  return <>{children}</>;
   108→}
   109→
   110→type RoleGuardProps = {
   111→  children: ReactNode;
   112→  roles: string[];
