   142→    if (!hasRole) {
   143→      if (redirectTo) {
   144→        redirect(redirectTo);
   145→      }
   146→      return <>{fallback}</>;
   147→    }
   148→  }
   149→
   150→  // For individuals, only check if they have the "individualBuyer" role
   151→  if (userContext.accountType === "individual") {
   152→    const hasRole = roles.includes("individualBuyer");
   153→
   154→    if (!hasRole) {
   155→      if (redirectTo) {
   156→        redirect(redirectTo);
   157→      }
   158→      return <>{fallback}</>;
   159→    }
   160→  }
   161→
   162→  return <>{children}</>;
   163→}
