    14→
    15→const getOrg = async () => {
    16→  const user = await getSession();
    17→
    18→  if (user?.session.activeOrganizationId) {
    19→    // Get organization directly from Prisma to include stripeCustomerId
    20→    return prisma.organization.findFirst({
    21→      where: { id: user.session.activeOrganizationId },
    22→      include: {
    23→        members: {
    24→          include: {
    25→            user: true,
    26→          },
    27→        },
    28→        invitations: true,
    29→      },
    30→    });
    31→  }
    32→
    33→  return null;
    34→};
    35→
    36→export const getCurrentOrg = async (params?: OrgParams) => {
    37→  const user = await getSession();
    38→
    39→  if (!user) {
    40→    return null;
    41→  }
    42→
    43→  const org = await getOrg();
    44→
    45→  if (!org) {
    46→    return null;
    47→  }
    48→
    49→  const memberRoles = org.members
    50→    .filter((member) => member.userId === user.session.userId)
    51→    .map((member) => member.role) as AuthRole[];
    52→
    53→  if (memberRoles.length === 0 || !isInRoles(memberRoles, params?.roles)) {
    54→    return null;
    55→  }
    56→
    57→  if (params?.permissions) {
    58→    const hasPermission = await auth.api.hasPermission({
    59→      headers: await headers(),
    60→      body: {
    61→        permission: params.permissions,
    62→      },
    63→    });
    64→
    65→    if (!hasPermission.success) {
    66→      return null;
    67→    }
    68→  }
    69→
    70→  const currentSubscription = await getOrgActiveSubscription(org.id);
    71→
    72→  const OWNER = org.members.find((m) => m.role === "owner");
    73→
    74→  return {
    75→    ...org,
    76→    slug: org.slug ?? "org-slug-default",
    77→    user: user.user,
    78→    email: (OWNER?.user.email ?? null) as string | null,
    79→    memberRoles: memberRoles,
    80→    subscription: currentSubscription ?? null,
    81→  };
    82→};
