     1→import { createZodRoute } from "next-zod-route";
     2→import { NextResponse } from "next/server";
     3→import { z } from "zod";
     4→import { AuthPermissionSchema, RolesKeys } from "./auth/auth-permissions";
     5→import { getUser } from "./auth/auth-user";
     6→import { logger } from "./logger";
     7→import { getCurrentOrg } from "./organizations/get-org";
     8→
     9→/**
    10→ * Custom error class for route validation and authorization failures
    11→ */
    12→export class ZodRouteError extends Error {
    13→  status?: number;
    14→  constructor(message: string, status?: number) {
    15→    super(message);
    16→    this.status = status ?? 400;
    17→  }
    18→}
    19→
    20→/**
    21→ * Base route handler with automatic error handling and validation
    22→ *
    23→ * @example
    24→ * ```ts
    25→ * export const POST = route
    26→ *   .params(z.object({ id: z.string() }))
    27→ *   .body(z.object({ name: z.string() }))
    28→ *   .handler(async (req, { params, body }) => {
    29→ *     return { success: true };
    30→ *   });
    31→ * ```
    32→ */
    33→export const route = createZodRoute({
    34→  handleServerError: (e: Error) => {
    35→    if (e instanceof ZodRouteError) {
    36→      logger.debug("[DEV] - ZodRouteError", e);
    37→      return NextResponse.json(
    38→        { message: e.message },
    39→        {
    40→          status: e.status,
    41→        },
    42→      );
    43→    }
    44→
    45→    logger.info("Unknown Error", e);
    46→
    47→    if (process.env.NODE_ENV === "development") {
    48→      return NextResponse.json({ message: e.message }, { status: 500 });
    49→    }
    50→
    51→    return NextResponse.json(
    52→      { message: "Internal server error" },
    53→      { status: 500 },
    54→    );
    55→  },
    56→});
    57→
    58→/**
    59→ * Route handler with authentication middleware
    60→ * Ensures user is logged in before accessing the route
    61→ */
    62→export const authRoute = route.use(async ({ next }) => {
    63→  const user = await getUser();
    64→
    65→  if (!user) {
    66→    throw new ZodRouteError("Session not found!", 401);
    67→  }
    68→
    69→  return next({
    70→    ctx: { user },
    71→  });
    72→});
    73→
    74→/**
    75→ * Route handler with organization-based authorization
    76→ * Validates user permissions within an organization context
    77→ *
    78→ * @example
    79→ * ```ts
    80→ * export const POST = orgRoute
    81→ *   .metadata({ permissions: { users: ["create"] } })
    82→ *   .handler(async (req, { ctx }) => {
    83→ *     // ctx.organization is available
    84→ *     return { success: true };
    85→ *   });
    86→ * ```
    87→ */
    88→export const orgRoute = route
    89→  .defineMetadata(
    90→    z.object({
    91→      roles: z.array(z.enum(RolesKeys)).optional(),
    92→      permissions: AuthPermissionSchema.optional(),
    93→    }),
    94→  )
    95→  .use(async ({ next, metadata }) => {
    96→    const organization = await getCurrentOrg(metadata);
    97→
    98→    if (!organization) {
    99→      throw new ZodRouteError(
   100→        "You need to be part of an organization to access this resource.",
   101→        401,
   102→      );
   103→    }
   104→
   105→    return next({
   106→      ctx: { organization },
   107→    });
   108→  });
   109→

