     4→import { searchPropertiesAction } from "@/features/properties/property-search.action";
     5→import {
     6→  DEFAULT_FILTERS,
     7→  type PropertySearchFilters,
     8→} from "@/features/properties/types";
     9→import { urlParamsToFilters } from "@/features/properties/filter-utils";
    10→import {
    11→  createSearchParamsCache,
    12→  parseAsInteger,
    13→  parseAsString,
    14→  parseAsStringEnum,
    15→} from "nuqs/server";
    16→import type { SearchResult } from "@/lib/moteurimmo/types";
    17→
    18→type PropertyPageProps = {
    19→  searchParams: Promise<Record<string, string | string[] | undefined>>;
    20→};
    21→
    22→// Server-side search params cache
    23→const searchParamsCache = createSearchParamsCache({
    24→  search: parseAsString.withDefault(DEFAULT_FILTERS.search),
    25→  type: parseAsString.withDefault(DEFAULT_FILTERS.type),
    26→  category: parseAsString.withDefault(DEFAULT_FILTERS.category),
    27→  priceMin: parseAsString.withDefault(DEFAULT_FILTERS.priceMin),
    28→  priceMax: parseAsString.withDefault(DEFAULT_FILTERS.priceMax),
    29→  surfaceMin: parseAsString.withDefault(DEFAULT_FILTERS.surfaceMin),
    30→  surfaceMax: parseAsString.withDefault(DEFAULT_FILTERS.surfaceMax),
    31→  rooms: parseAsString.withDefault(DEFAULT_FILTERS.rooms),
    32→  bedrooms: parseAsString.withDefault(DEFAULT_FILTERS.bedrooms),
    33→  city: parseAsString.withDefault(DEFAULT_FILTERS.city),
    34→  selectedCitiesJson: parseAsString.withDefault(""),
    35→  selectedTypesJson: parseAsString.withDefault(""),
    36→  selectedCategoriesJson: parseAsString.withDefault(""),
    37→  selectedPublisherTypesJson: parseAsString.withDefault(""),
    38→  selectedEquipmentJson: parseAsString.withDefault(""),
    39→  page: parseAsInteger.withDefault(DEFAULT_FILTERS.page),
    40→  sortBy: parseAsString.withDefault(DEFAULT_FILTERS.sortBy),
    41→  sortOrder: parseAsStringEnum(["asc", "desc"]).withDefault(
    42→    DEFAULT_FILTERS.sortOrder,
    43→  ),
    44→  view: parseAsStringEnum(["list", "grid"]).withDefault(DEFAULT_FILTERS.view),
    45→});
    46→
    47→async function PropertyContent({
    48→  searchParams,
    49→}: {
    50→  searchParams: Record<string, string | string[] | undefined>;
    51→}) {
    52→  // Parse search params using nuqs server cache
    53→  const parsedFilters = searchParamsCache.parse(searchParams);
    54→
    55→  // Only search if we have some filters (avoid empty search on page load)
    56→  const hasActiveFilters =
    57→    parsedFilters.selectedCitiesJson ||
    58→    parsedFilters.selectedTypesJson ||
    59→    parsedFilters.selectedCategoriesJson ||
    60→    parsedFilters.priceMin ||
    61→    parsedFilters.priceMax ||
    62→    parsedFilters.surfaceMin ||
    63→    parsedFilters.surfaceMax ||
    64→    parsedFilters.rooms ||
    65→    parsedFilters.bedrooms ||
    66→    parsedFilters.city ||
    67→    parsedFilters.search;
    68→
    69→  let searchResult = { data: null, error: null } as {
    70→    data: SearchResult | null;
    71→    error: string | null;
    72→  };
    73→
    74→  if (hasActiveFilters) {
    75→    // Convert URL params to PropertySearchFilters only when needed
    76→    const filters: PropertySearchFilters = urlParamsToFilters(parsedFilters);
    77→    searchResult = await searchPropertiesAction(filters);
    78→  }
    79→
    80→  return (
    81→    <div className="container mx-auto px-4 py-6">
    82→      <div className="mb-8">
    83→        <h1 className="mb-2 text-3xl font-bold">
    84→          Recherche de biens immobiliers
    85→        </h1>
    86→        <p className="text-muted-foreground">
    87→          Trouvez le bien immobilier parfait grâce à notre moteur de recherche
    88→          avancé.
    89→        </p>
    90→      </div>
    91→
    92→      {/* Filters - Collapsible panel at top */}
    93→      <PropertyFiltersToggle searchResult={searchResult.data} />
    94→
    95→      {/* Results */}
    96→      <PropertyList
    97→        data={searchResult.data}
    98→        error={searchResult.error}
    99→        isLoading={false}
   100→      />
   101→    </div>
   102→  );
   103→}
   104→
   105→export default async function PropertiesPage({
   106→  searchParams,
   107→}: PropertyPageProps) {
   108→  const resolvedSearchParams = await searchParams;
   109→
   110→  return (
   111→    <Suspense
   112→      fallback={
   113→        <div className="container mx-auto px-4 py-6">
   114→          <div className="mb-8">
   115→            <div className="bg-muted mb-2 h-8 w-64 animate-pulse rounded" />
   116→            <div className="bg-muted h-4 w-96 animate-pulse rounded" />
   117→          </div>
   118→
   119→          {/* Filters skeleton */}
   120→          <div className="bg-muted mb-6 h-16 animate-pulse rounded" />
   121→
   122→          {/* Results skeleton */}
   123→          <div className="space-y-4">
   124→            {Array.from({ length: 3 }).map((_, i) => (
   125→              <div key={i} className="bg-muted h-48 animate-pulse rounded" />
   126→            ))}
   127→          </div>
   128→        </div>
   129→      }
   130→    >
   131→      <PropertyContent searchParams={resolvedSearchParams} />
   132→    </Suspense>
   133→  );
   134→}
